import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.Rqo6UvEC.js";const b=JSON.parse('{"title":"3D 打印指南","description":"","frontmatter":{},"headers":[],"relativePath":"02-3d-printing.md","filePath":"02-3d-printing.md","lastUpdated":1785555913000}'),l={name:"02-3d-printing.md"};function o(i,t,n,c,s,h){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_3d-打印指南" tabindex="-1">3D 打印指南 <a class="header-anchor" href="#_3d-打印指南" aria-label="Permalink to &quot;3D 打印指南&quot;">​</a></h1><blockquote><p><strong>预计时间：约 34 小时</strong></p></blockquote><p>所有 STL 文件位于 <code>Code/3DPrintMeshes/</code> 目录。使用通用 PLA 耗材在消费级 FDM 打印机上即可打印，已在 Bambu Lab P1S 上完成测试验证。</p><h2 id="stl-零件清单" tabindex="-1">STL 零件清单 <a class="header-anchor" href="#stl-零件清单" aria-label="Permalink to &quot;STL 零件清单&quot;">​</a></h2><h3 id="标准版本-12v-有线通用" tabindex="-1">标准版本（12V / 有线通用） <a class="header-anchor" href="#标准版本-12v-有线通用" aria-label="Permalink to &quot;标准版本（12V / 有线通用）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>零件</th><th>文件路径</th><th style="text-align:center;">数量</th><th>备注</th></tr></thead><tbody><tr><td>底板顶层</td><td><code>base_plate_layer2.stl</code></td><td style="text-align:center;">1</td><td></td></tr><tr><td>底板底层</td><td><code>base_plate_layer1.stl</code></td><td style="text-align:center;">1</td><td></td></tr><tr><td>驱动电机支架</td><td><code>drive_motor_mount_v2.stl</code></td><td style="text-align:center;">3</td><td></td></tr><tr><td>舵机轮毂</td><td><code>servo_wheel_hub.stl</code></td><td style="text-align:center;">3</td><td>⚠️ 需要支撑</td></tr><tr><td>舵机控制器支架</td><td><code>servo_controller_mount.stl</code></td><td style="text-align:center;">1</td><td></td></tr><tr><td>电池支架 (12V)</td><td><code>battery_mount.stl</code></td><td style="text-align:center;">1</td><td>12V 版本</td></tr><tr><td>电池支架 (12V EU)</td><td><code>battery_mount_eu.stl</code></td><td style="text-align:center;">1</td><td>12V 欧洲版</td></tr><tr><td>树莓派外壳顶部</td><td><code>pi_case_top.stl</code></td><td style="text-align:center;">1</td><td></td></tr><tr><td>树莓派外壳底部</td><td><code>pi_case_bottom.stl</code></td><td style="text-align:center;">1</td><td></td></tr><tr><td>摄像头底座支架</td><td><code>base_camera_mount.stl</code></td><td style="text-align:center;">1</td><td>Arducam 方案</td></tr><tr><td>摄像头腕部支架</td><td><code>wrist_camera_mount.stl</code></td><td style="text-align:center;">1</td><td>Arducam 方案</td></tr><tr><td>网络摄像头底座支架</td><td><code>webcam_mount/webcam_mount.stl</code></td><td style="text-align:center;">1</td><td>USB 摄像头方案</td></tr><tr><td>网络摄像头夹持器插入件</td><td><code>webcam_mount/so100_gripper_cam_mount_insert.stl</code></td><td style="text-align:center;">1</td><td>USB 摄像头方案</td></tr><tr><td>网络摄像头腕部支架</td><td><code>webcam_mount/webcam_mount_wrist.stl</code></td><td style="text-align:center;">1</td><td>USB 摄像头方案</td></tr><tr><td>修改版从臂底座</td><td><code>modified_base_arm.stl</code></td><td style="text-align:center;">1</td><td>⚠️ 树形支撑</td></tr></tbody></table><h3 id="有线版本额外零件" tabindex="-1">有线版本额外零件 <a class="header-anchor" href="#有线版本额外零件" aria-label="Permalink to &quot;有线版本额外零件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>零件</th><th>文件路径</th><th style="text-align:center;">数量</th></tr></thead><tbody><tr><td>线缆夹</td><td><code>wired_specific/cable_holder v0.stl</code></td><td style="text-align:center;">1</td></tr><tr><td>USB 连接器外壳</td><td><code>wired_specific/usb_connector_case v1.stl</code></td><td style="text-align:center;">1</td></tr></tbody></table><h3 id="so-arm100-手臂零件-外部" tabindex="-1">SO-ARM100 手臂零件（外部） <a class="header-anchor" href="#so-arm100-手臂零件-外部" aria-label="Permalink to &quot;SO-ARM100 手臂零件（外部）&quot;">​</a></h3><p>从 <a href="https://github.com/TheRobotStudio/SO-ARM100" target="_blank" rel="noreferrer">SO-ARM100 仓库</a> 打印：</p><ul><li>从臂（Follower arm）× 1</li><li>主臂（Leader arm）× 1</li></ul><h2 id="打印参数" tabindex="-1">打印参数 <a class="header-anchor" href="#打印参数" aria-label="Permalink to &quot;打印参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>推荐值</th><th>备注</th></tr></thead><tbody><tr><td>材料</td><td>PLA / PLA+</td><td>通用即可</td></tr><tr><td>喷嘴直径</td><td>0.2 mm</td><td></td></tr><tr><td>层高</td><td>0.2 mm</td><td></td></tr><tr><td>填充密度</td><td>15%</td><td></td></tr><tr><td>打印速度</td><td>150 mm/s</td><td></td></tr><tr><td>支撑</td><td>按需开启</td><td>仅标记了「需要支撑」的零件</td></tr></tbody></table><h2 id="打印步骤" tabindex="-1">打印步骤 <a class="header-anchor" href="#打印步骤" aria-label="Permalink to &quot;打印步骤&quot;">​</a></h2><ol><li>将 STL 文件导入切片软件（Bambu Studio、PrusaSlicer 等）</li><li>对标记为「需要支撑」的零件启用支撑</li><li>使用推荐参数切片，上传 G-code 到打印机</li></ol><h3 id="后处理" tabindex="-1">后处理 <a class="header-anchor" href="#后处理" aria-label="Permalink to &quot;后处理&quot;">​</a></h3><ul><li>从打印平台取下打印件</li><li>拆除支撑结构</li><li>检查螺丝孔是否通畅（如需可用钻头清理）</li></ul><h2 id="没有-3d-打印机" tabindex="-1">没有 3D 打印机？ <a class="header-anchor" href="#没有-3d-打印机" aria-label="Permalink to &quot;没有 3D 打印机？&quot;">​</a></h2><p>可以选择在线 3D 打印服务，或选购市面上已有的套件。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>前往 <a href="/qiyue-tanwei-website/lekiwi/03-assembly.html">组装指南</a> 开始组装！</p>',21)])])}const m=d(l,[["render",o]]);export{b as __pageData,m as default};
